import re
from typing import Any


def od_rows(type_slug: str, q: str = "") -> list[dict[str, Any]]:
    out: list[dict[str, Any]] = []
    cursor: str | None = None
    for _ in range(100):
        if q:
            page = api.records.list(type_slug=type_slug, limit=200, cursor=cursor, q=q)
        else:
            page = api.records.list(type_slug=type_slug, limit=200, cursor=cursor)
        out.extend(page.get("records") or [])
        cursor = page.get("nextCursor")
        if not cursor:
            break
    return out


def od_data(row: Any) -> dict[str, Any]:
    return dict((row or {}).get("data") or {})


def od_text(value: Any) -> str:
    return str(value).strip() if value is not None else ""


def od_norm(value: Any) -> str:
    return re.sub(r"[^a-z0-9]+", " ", od_text(value).lower()).strip()


def od_link_ids(row: Any, field: str) -> list[str]:
    out: list[str] = []
    for ref in ((row or {}).get("links") or {}).get(field) or []:
        if isinstance(ref, dict) and ref.get("id"):
            out.append(str(ref["id"]))
        elif isinstance(ref, str):
            out.append(ref)
    return out


def od_order_lines(order_id: str, order_number: str) -> list[dict[str, Any]]:
    found = [r for r in od_rows("od_order_lines", order_number) if order_id in od_link_ids(r, "order")]
    if not found:
        found = [r for r in od_rows("od_order_lines") if order_id in od_link_ids(r, "order")]
    found.sort(key=lambda r: float(od_data(r).get("line_number") or 0))
    return found


def as_number(value: Any) -> float:
    try:
        return float(re.sub(r"[^0-9.\-]", "", str(value)) or 0)
    except ValueError:
        return 0.0


order_id = params["order_id"]
found = api.records.get(type_slug="od_orders", record_id=order_id) or {}
order: dict[str, Any] = dict(found.get("record") or {})
order_number = od_text(order.get("title"))
stage = od_text(order.get("stage"))
account_code = od_text(od_data(order).get("account_code"))
if stage in ("released", "rejected", "not_an_order"):
    raise ValueError("Order " + order_number + " is already " + stage.replace("_", " ") + ", so its lines can no longer be changed.")
wanted: dict[int, dict[str, Any]] = {}
for item in (params.get("changed_lines") or []):
    if isinstance(item, dict) and item.get("line_number") is not None:
        wanted.setdefault(int(as_number(item.get("line_number"))), {}).update({k: item.get(k) for k in ("item_code", "quantity", "unit") if item.get(k) is not None})
for item in (params.get("changes") or []):
    if isinstance(item, dict) and od_text(item.get("column")) in ("item_code", "quantity", "unit") and od_text(item.get("row")) != "":
        wanted.setdefault(int(as_number(item.get("row"))), {})[od_text(item.get("column"))] = item.get("value")
catalogue = [r for r in od_rows("od_customer_catalogue", account_code) if od_text(od_data(r).get("account_code")) == account_code] if account_code and wanted else []
products = od_rows("od_products") if any(od_text(w.get("item_code")) for w in wanted.values()) else []
fixed = 0
learned_count = 0
not_found: list[int] = sorted(wanted.keys())
unknown_codes: list[str] = []
for row in (od_order_lines(order_id, order_number) if wanted else []):
    line_id = od_text(row.get("id"))
    d = od_data(row)
    number = int(as_number(d.get("line_number")))
    want = wanted.get(number)
    if want is None:
        continue
    if number in not_found:
        not_found.remove(number)
    label = od_text(row.get("title"))
    patch: dict[str, Any] = {}
    line_links: dict[str, Any] = {}
    product_changed = False
    new_code = od_text(want.get("item_code"))
    if new_code and new_code.upper() != od_text(d.get("item_code")).upper():
        hit = [p for p in products if od_text(od_data(p).get("item_code")).upper() == new_code.upper()]
        if not hit:
            unknown_codes.append(new_code)
            continue
        patch["item_code"] = od_text(od_data(hit[0]).get("item_code"))
        patch["match_result"] = "matched"
        line_links["product"] = [hit[0]["id"]]
        product_changed = True
        if od_text(want.get("unit")) == "" and od_text(od_data(hit[0]).get("sell_unit")):
            patch["unit"] = od_text(od_data(hit[0]).get("sell_unit"))[:40]
    if od_text(want.get("quantity")) != "" and abs(as_number(want.get("quantity")) - as_number(d.get("quantity"))) > 0.0005:
        patch["quantity"] = round(as_number(want.get("quantity")), 3)
    new_unit = od_text(want.get("unit"))
    if new_unit and new_unit != od_text(d.get("unit")):
        patch["unit"] = new_unit[:40]
    if not patch:
        continue
    d.update(patch)
    customer_code = od_text(d.get("customer_code"))
    item_code = od_text(d.get("item_code"))
    if account_code and item_code and product_changed and (customer_code or od_text(d.get("raw_text"))):
        description = od_text(d.get("raw_text"))
        if customer_code:
            description = description.replace(customer_code, " ")
        description = re.sub(r"(?i)\b(x|\d+(\.\d+)?|" + re.escape(od_text(d.get("raw_unit"))) + r")\b" if od_text(d.get("raw_unit")) else r"(?i)\b(x|\d+(\.\d+)?)\b", " ", description)
        description = re.sub(r"\s+", " ", description).strip()[:300]
        known = [r for r in catalogue if (customer_code and od_text(od_data(r).get("customer_code")).upper() == customer_code.upper()) or (not customer_code and od_norm(od_data(r).get("customer_description")) == od_norm(description))]
        mapping: dict[str, Any] = {"account_code": account_code, "customer_code": customer_code[:120], "customer_description": description, "customer_unit": od_text(d.get("raw_unit"))[:40], "item_code": item_code, "conversion_factor": 1, "rounding": "none", "source": "learned", "mapping_notes": "Learned from a correction on " + label + "."}
        links: dict[str, Any] = {"product": list(line_links["product"])[:1]}
        if known:
            api.records.update(type_slug="od_customer_catalogue", record_id=known[0]["id"], record={"data": {"item_code": item_code, "source": "learned", "mapping_notes": mapping["mapping_notes"]}, "links": links})
        else:
            api.records.create(type_slug="od_customer_catalogue", record={"title": (account_code + " / " + (customer_code or description))[:200], "data": mapping, "links": links})
        learned_count += 1
    patch.update({"corrected": True, "needs_review": False, "conversion_note": "Corrected by a reviewer."})
    api.records.update(type_slug="od_order_lines", record_id=line_id, record={"data": patch, "links": line_links} if line_links else {"data": patch})
    fixed += 1
if fixed:
    api.records.update(type_slug="od_orders", record_id=order_id, record={"data": {"auto_confirmed": False, "check_stamp": ""}})
problems: list[str] = []
if unknown_codes:
    problems.append("Not changed, because no product has this item code: " + ", ".join(sorted(set(unknown_codes))[:20]) + ".")
if not_found:
    problems.append("Not changed, because the order has no line numbered: " + ", ".join(str(n) for n in not_found[:20]) + ".")
result = (str(fixed) + (" line" if fixed == 1 else " lines") + " corrected. " + " ".join(problems)).strip()
